/* Apresentação BRL compartilhada. Valores persistidos continuam numéricos. */
(function(root){'use strict';const cache=new WeakMap(),fmt=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:2,maximumFractionDigits:2});
function parse(value){let s=String(value??'').trim().replace(/R\$/g,'').replace(/\s/g,'');if(!s)return '';if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');if(!/^[+-]?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?$/i.test(s)||!Number.isFinite(Number(s)))throw Error('Valor monetário inválido.');return String(Number(s))}
function format(value){return value===null||value===undefined||value===''?'':fmt.format(Number(parse(value))).replace(/\s/g,'')}
function read(el){let c=cache.get(el);return c&&el.value===c.display?c.raw:String(el.value??'')}
function monetary(el){if(el.tagName!=='INPUT'||['checkbox','radio','file','date','search','email','tel','password'].includes(el.type))return false;if(el.dataset?.money!==undefined)return true;let d=el.dataset||{},key=d.purchaseHeader||d.key||d.laborField;if((d.purchaseItem!==undefined&&['unitPrice','total'].includes(key))||(d.purchasePart!==undefined&&key==='amount')||(d.laborRow!==undefined&&key==='amount')||d.purchaseHeader==='adjustment'||d.laborField==='amount')return true;let label=(el.getAttribute?.('aria-label')||'')+' '+(el.labels?Array.from(el.labels).map(l=>l.textContent).join(' '):el.closest?.('label')?.textContent||'');return /R\$/.test(label)||el.id==='paymentAmount'}
function paint(el){if(root.document?.activeElement===el)return;try{let raw=parse(read(el)),display=format(raw);el.value=display;cache.set(el,{raw,display})}catch{}}
function attach(el){if(!monetary(el))return;el.dataset.money='';if(el.type==='number')el.type='text';el.inputMode='decimal';if(!el.dataset.currencyBound){el.dataset.currencyBound='1';el.addEventListener('focus',()=>{try{el.value=parse(read(el))}catch{} });el.addEventListener('blur',()=>paint(el));el.addEventListener('input',()=>{cache.delete(el);if(root.queueMicrotask)root.queueMicrotask(scan)})}paint(el)}
function scan(){for(let el of root.document?.querySelectorAll('input')||[])attach(el)}
root.EngefexCurrency={parse,format,read,monetary,attach,scan,number(value){try{return Number(parse(value))}catch{return NaN}}};if(root.document&&root.MutationObserver){let queued=false;new root.MutationObserver(()=>{if(queued)return;queued=true;root.queueMicrotask(()=>{queued=false;scan()})}).observe(root.document.documentElement,{childList:true,subtree:true});scan()}
})(typeof window==='undefined'?globalThis:window);
